local GamePlayer = class("GamePlayer", BasePlayer)
local customGame = T(Global, "customGame")

function GamePlayer:init()
    self.isLife = true
    self.score = 0
    self.isSleeping = false
    self:initStaticAttr(0)
    if self.clientPeer then
        self.clientPeer:rebirth()
    end
    customGame:onPlayerLogin(self)
    self.permissionRole = customGame:getDefaultPermissionRole()
    if customGame:getOwnerId() == self.userId then 
        self.permissionRole = Define.CustomGamePermissionRole.Owner
    end
    self.permissionRole = self.permissionRole or Define.CustomGamePermissionRole.Member
    self.bedInfo = {}
    self.permissionSetting = customGame:getDefaultPermByRole(self.permissionRole)
    -- self.isOldPermMgrPlayer = true --初始化为旧版玩家。收到1100007才设置为新版玩家
    self.isOldPermMgrPlayer = false
    print("GamePlayerInit permissionRole "..self.permissionRole)
    print("GamePlayerInit permissionSetting "..StringUtil.v2s(self.permissionSetting))
    self:initConfigBySetting()
    local this = self
    LuaTimer:scheduleTimer(
        function()
            self:sendPacket({
                pid = "syncCustomRoomInfo",
                data = {
                    mode = customGame:getGameMode(),
                    setting = self.permissionSetting,
                    globalSetting = customGame:getGlobalPermSetting(),
                    ugcSetting = customGame:getUGCRunningSetting(),
                    ugcExtraConfig = customGame:getUGCExtraConfig()
                }
            })
            this:setAllowFlying(this.userId == 320 or (this:getPermissionSetting(Define.CustomRoomSettingType.FLY) or false))
            customGame:onPlayerLoginAfter1Sec(this)
        end, 1000, 1)
    self:sendPacket({
        pid = "syncPermissionRole",
        role = self.permissionRole
    })
end

function GamePlayer:initConfigBySetting()
    self:setNeedFoodStats(self:getPermissionSetting(Define.CustomRoomSettingType.FOOD) or false)
    self:rebirth(false)
end

function GamePlayer:setNeedFoodStats(value)
    self.entityPlayerMP:setBoolProperty("NeedFoodStats", value)
end

function GamePlayer:rebirth(isRebirth)
    self.isLife = true
    self:changeMaxHealth(20)
    self:setFoodLevel(20)
    self:setAllowFlying(self.userId == 320 or (self:getPermissionSetting(Define.CustomRoomSettingType.FLY) or false))
    --self:setFlying(self:getPermissionSetting(Define.CustomRoomSettingType.FLY) or false)
    if not customGame:canDeathDropItem(self) then
        self:fillInvetory(self.inventory)
    end
    if isRebirth == true then
        customGame:onPlayerRebirth(self)
    end
    if self.respawnOnBed then
        LuaTimer:schedule(function(userId)
            ---@type GamePlayer
            local _player = PlayerManager:getPlayerByUserId(userId)
            if _player then
                _player:setSleep()
            end
        end, 700, nil, self.userId)
    end
end

function GamePlayer:getPermissionSetting(perm)
    if customGame.globalPermSetting[perm] ~= nil and not customGame.globalPermSetting[perm] then
        return false
    end

    --如果有个人设置 则返回个人设置
    if self.permissionSetting[perm] ~= nil then
        return self.permissionSetting[perm]
    end

    --如果没有个人设置 则返回true
    return true
end

function GamePlayer:getPermissionRole()
    return self.permissionRole
end

function GamePlayer:updatePermission(perm, value)
    self.permissionSetting[perm] = value
    if perm == Define.CustomRoomSettingType.FOOD then
        self:setNeedFoodStats(value)
    elseif perm == Define.CustomRoomSettingType.FLY then
        if customGame:getGlobalPermSetting()[Define.CustomRoomSettingType.FLY] then 
            self:setAllowFlying(self.userId == 320 or value)
            self:setFlying(value)
        end
    end
end

function GamePlayer:globalChangeFlyPermStatus(value)
    if value and self.permissionSetting[Define.CustomRoomSettingType.FLY] then 
        self:setAllowFlying(true)
        self:setFlying(true)
    else
        self:setAllowFlying(self.userId == 320 or false)
        self:setFlying(false)
    end
end

function GamePlayer:notifyUpdatePermSettingv1()
    self:sendPacket({
        pid = "updateCustomRoomPermSetting",
        data = self.permissionSetting
    })
end

function GamePlayer:updatePermissionSetingList(fromUserName, fromType, roleType, setting)
    local updateSetting = setting
    --print("updatePermissionSetingList 02 "..StringUtil.v2s(roleType).." old "..StringUtil.v2s(self.permissionRole))
    if self.permissionRole ~= roleType then
        PacketSender:broadCastPidPacket({
            pid = "updateCustomRoomRoleType",
            data ={
                userId = self.userId,
                userName = self.name,
                fromType = fromType,
                oldType = self.permissionRole,
                newType = roleType
            }
        })
        self.permissionRole = roleType
        updateSetting = customGame:getDefaultPermByRole(roleType)
        --print("begin update user perm "..tostring(self.userId)..StringUtil.v2s(updateSetting))
        for i, v in pairs(updateSetting) do
            self:updatePermission(i, v)
        end
        self:sendPacket({
            pid = "syncPermissionRole",
            role = self.permissionRole
        })
    else
        for i, v in pairs(updateSetting) do
            self:updatePermission(v.id, v.switch)
        end
    end

    self:sendPacket({
        pid = "updateCustomRoomPermSettingForUser",
        data = {
            perms = self.permissionSetting,
            editor = fromUserName
        }
    })
end

function GamePlayer:resetScore()
    self.score = 0
    self.killNum = 0
end

function GamePlayer:onKill()
    self.killNum = self.killNum + 1
end

function GamePlayer:onDie()
    self.dieNum = self.dieNum + 1
end

function GamePlayer:setSleep()
    if self.bedInfo and self.bedInfo.pos then
        local blockId1 = EngineWorld:getBlockId(self.bedInfo.bedPos[1])
        local blockId2 = EngineWorld:getBlockId(self.bedInfo.bedPos[2])
        if blockId1 ~= BlockID.BED or blockId2 ~= BlockID.BED then
            return
        end
        local players = PlayerManager:getPlayers()
        for i, player in pairs(players) do
            if player.userId ~= self.userId and player.isSleeping and player.bedInfo and player.bedInfo.pos
                    and self.bedInfo.pos.x == player.bedInfo.pos.x
                    and self.bedInfo.pos.y == player.bedInfo.pos.y
                    and self.bedInfo.pos.z == player.bedInfo.pos.z then
                return
            end
        end
        self.isSleeping = true
        local pos = self.bedInfo.pos
        local yaw = self.bedInfo.yaw
        self.entityPlayerMP:setDisableMove(1000)
        self:teleportPosWithYaw(VectorUtil.add3(self.bedInfo.pos, VectorUtil.newVector3(0, -0.5 + 0.1, 0)), self.bedInfo.yaw)
        PacketSender:broadCastPidPacket({
            pid = "setSleep",
            playerId = self.userId,
            pos = pos,
            yaw = yaw
        })
    end
end

function GamePlayer:cancelSleep(willDead)
    if willDead or not self.isSleeping then
        return
    end
    self.isSleeping = false
    PacketSender:broadCastPidPacket({
        pid = "cancelSleep",
        playerId = self.userId
    })
end

function GamePlayer:getItemCount(id, meta)
    local inventory = self:getInventory()
    local count = 0
    for i = 0, 35 do
        local info = inventory:getItemStackInfo(i)
        if info.id == id and info.meta == meta then
            count = count + info.num
        end
    end
    return count
end

function GamePlayer:checkCanAddItem(id, meta, num)
    local inventory = self:getInventory()
    return inventory:isCanAddItem(id, meta, num)
end

function GamePlayer:teleportToTeamInit()
    local pos = VectorUtil.toVector3(customGame:getInitPos())
    if self.teamId and self.teamId ~= 0 then
        local team = customGame:getTeam(self.teamId)
        if team then
            pos = VectorUtil.toVector3(team.initPos)
        end
    end
    pos.y = pos.y - 0.5
    -- print("teleportToTeamInit x:" .. pos.x .. " y:" .. pos.y .. " z:" .. pos.z)
    self:teleportPos(pos)
end

function GamePlayer:buildShowName()
    local nameList = {}
    if customGame:getGameMode() == Define.CustomGameMode.EDIT then
        if self.staticAttr.role ~= -1 then
            table.insert(nameList, self:getClanName())
        end
    elseif customGame:getGameMode() == Define.CustomGameMode.RUN then
        if self.teamId and self.teamId ~= 0 then
            table.insert(nameList, self:getTeamName(self.teamId))
        else
            if self.staticAttr.role ~= -1 then
                table.insert(nameList, self:getClanName())
            end
        end
    end
    PlayerIdentityCache:buildNameList(self, nameList, self.name)
    return nameList
end

function GamePlayer:getTeamName(teamId)
    local name = TextFormat.colorStart .. "FF" .. Define.TeamFlagColor[teamId]
    if BaseMain:isChina() then
        name = name .. "队伍"
    else
        name = name .. "Team"
    end
    name = name .. tostring(teamId) .. string.format("[H=%s,2,0.6,0.6,0.6,0.85]", Define.TeamFlagEffect[teamId]) .. TextFormat.colorEnd
    return name
end

function GamePlayer:setTeamId(teamId)
    if self.teamId ~= teamId then
        self.teamId = teamId
        PacketSender:broadCastPidPacket({
            pid = "setTeamId",
            userId = self.userId,
            teamId = self.teamId
        })
    end
end

return GamePlayer